{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 조례상 자전거 안전교육에서 교통법규만 배우는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제13조제1항에 따르면 시장이 실시하는 자전거 이용 관련 교육에는 자전거 통행원칙 및 통행방법(제1호)과 자전거운전자의 준수사항 등 자전거 관련 교통법규(제2호) 외에도 자전거의 점검 및 관리 방법(제3호)과 그 밖에 안전한 자전거 이용을 위하여 필요한 사항(제4호)이 포함된다. 따라서 교통법규만 배우는 것이 아니라 점검·관리 방법 등도 교육 내용에 포함된다.",
          "b_ids": "자전거:제13조제1항, 자전거:제13조제1항제1호, 자전거:제13조제1항제2호, 자전거:제13조제1항제3호, 자전거:제13조제1항제4호"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "서울특별시 조례상 자전거 안전교육 내용에 브레이크·타이어 등 점검·관리 방법 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울특별시 자전거이용 활성화에 관한 조례 제13조제1항제3호는 시장이 실시하는 자전거 이용 관련 교육에 ‘자전거의 점검 및 관리 방법’을 포함하도록 정하고 있다. 따라서 브레이크나 타이어 같은 자전거의 점검·관리 방법도 교육 내용에 들어간다.",
          "b_ids": "자전거:제13조제1항제3호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
